import json
from typing import Any, Dict
async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    record_json = ''
    offer_id = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                record_json = str(first.get('result_json') or '')
        elif isinstance(arr, dict):
            record_json = str(arr.get('result_json') or '')
    except Exception:
        record_json = ''
    if not record_json:
        record_json = raw
    try:
        inner = json.loads(record_json)
        if isinstance(inner, dict):
            offer_id = str(inner.get('offer_id') or inner.get('offerId') or '')
    except Exception:
        offer_id = ''
    ret: Output = {
        "record_json": record_json,
        "offer_id": offer_id
    }
    return ret

import json, random
from typing import Any, Dict

async def main(args):
    p = args.params
    def _str(v):
        return str(v).strip() if v not in (None, '') else ''
    offer_id = _str(p.get('existing_offer_id') or '')
    if not offer_id:
        # 兜底：从执行方案原文解析内层 JSON 取 offer_id/similarOfferId
        raw = p.get('plan_json') or ''
        try:
            obj = json.loads(raw) if isinstance(raw, str) else raw
            if isinstance(obj, dict):
                offer_id = _str(obj.get('offer_id') or obj.get('offerId') or '')
                if not offer_id:
                    offer_id = _str(obj.get('similarOfferId') or '')
        except Exception:
            offer_id = ''
    # 校验：合法 9 位数字编码才透传（存量重配），否则生成全新 900 编码
    if offer_id.isdigit() and len(offer_id) == 9:
        pass
    else:
        offer_id = '900%06d' % random.randint(0, 999999)
    ret: Output = {'offer_id': offer_id}
    return ret

import json
from typing import Any, Dict

def _load(text):
    if not isinstance(text, str) or not text.strip():
        return {}
    try:
        return json.loads(text)
    except Exception:
        try:
            t = text.strip()
            if ':' in t and not t.startswith('{') and not t.startswith('['):
                t = t.split(':', 1)[1].strip()
            return json.loads(t)
        except Exception:
            return {}

async def main(args):
    p = args.params
    cfg = _load(p.get('group_json') or '')
    raw_status = str(p.get('status') or '')
    merged = cfg.get('group') if isinstance(cfg.get('group'), dict) else None
    if not merged:
        ret: Output = {'fusion_echo': '', 'fusion_status': raw_status, 'fusion_note': ''}
        return ret
    members = merged.get('members') or []
    parts = []
    failed = []
    for m in members:
        role = str(m.get('role') or '')
        oid = str(m.get('offer_id') or '')
        if role:
            parts.append('%s（offer_id %s）' % (role, oid))
        m_status = str(m.get('status') or '').upper()
        if m_status in ('PARTIAL', 'FAIL'):
            failed.append('%s=%s' % (role or oid, m_status))
    main_id = str(merged.get('main_offer_id') or cfg.get('offer_id') or '')
    line = '融合成员：'
    if main_id:
        line += '主 offer_id %s / ' % main_id
    line += ' / '.join(parts) if parts else ''
    fusion_status = raw_status.upper()
    if failed and fusion_status == 'SUCCESS':
        fusion_status = 'PARTIAL'
    note = ''
    if fusion_status == 'PARTIAL':
        detail = '、'.join(failed) if failed else '详见失败明细'
        note = '融合组部分成功（%s）：请按失败明细说明修改意见或回复【重新执行】' % detail
    elif fusion_status == 'FAIL':
        note = '融合组配置失败：请按失败明细说明修改意见或回复【重新执行】'
    ret: Output = {
        "fusion_echo": line if parts else '',
        "fusion_status": fusion_status,
        "fusion_note": note,
    }
    return ret

import json
from typing import Any, Dict

def _load(text):
    if isinstance(text, dict):
        return text
    if not isinstance(text, str) or not text.strip():
        return {}
    try:
        return json.loads(text)
    except Exception:
        try:
            t = text.strip()
            if ':' in t and not t.startswith('{') and not t.startswith('['):
                t = t.split(':', 1)[1].strip()
            return json.loads(t)
        except Exception:
            return {}

def _cell(v):
    return str(v) if v not in (None, '') else '—'

async def main(args):
    cfg = _load(args.params.get('product_config') or '')
    if not cfg:
        ret: Output = {'config_summary': ''}
        return ret
    plan = cfg.get('plan_json') if isinstance(cfg.get('plan_json'), dict) else {}
    info = plan.get('optionalInfo') if isinstance(plan.get('optionalInfo'), dict) else {}
    print_c = info.get('printContent') if isinstance(info.get('printContent'), dict) else {}
    gprs = info.get('billGprsCfg') if isinstance(info.get('billGprsCfg'), dict) else {}
    voice = info.get('billVoiceCfg') if isinstance(info.get('billVoiceCfg'), dict) else {}
    base = plan.get('baseInfo') if isinstance(plan.get('baseInfo'), dict) else {}
    in_fee = cfg.get('in_fee') if isinstance(cfg.get('in_fee'), dict) else {}
    out_fee = cfg.get('out_fee') if isinstance(cfg.get('out_fee'), dict) else {}
    offer_name = str(base.get('prodPrcName') or cfg.get('offer_name') or '').strip()
    fee = str(print_c.get('prcMonthFee') or base.get('fixFee') or '').strip()
    gift = str(print_c.get('containResource') or '').strip()
    if not gift:
        parts = []
        if str(gprs.get('theshold') or '').strip():
            parts.append('国内通用流量 %s%s' % (gprs.get('theshold'), gprs.get('unit') or ''))
        if str(voice.get('theshold') or '').strip():
            parts.append('国内通话 %s分钟' % voice.get('theshold'))
        gift = '、'.join(parts)
    out_price = str(print_c.get('chargeStandard') or '').strip()
    if not out_price:
        parts = []
        if str(gprs.get('outChargeMode') or '').strip():
            parts.append('套外流量 %s' % gprs.get('outChargeMode'))
        if str(voice.get('outCharge') or '').strip():
            parts.append('套外语音 %s元/分钟' % voice.get('outCharge'))
        out_price = '、'.join(parts)
    cycle = str(in_fee.get('计费周期') or '').strip()
    carry = '是' if str(gprs.get('carryFlag') or '').strip() in ('是', 'true', 'True', '1') else ''
    lines = ['【配置销售品要点简介】']
    lines.append('- 销售品名称：%s' % _cell(offer_name))
    lines.append('- 套餐档位（月费）：%s' % ((fee + ' 元/月') if fee else '—'))
    lines.append('- 套内资源：%s' % _cell(gift))
    lines.append('- 套外资费：%s' % _cell(out_price))
    if cycle:
        lines.append('- 计费周期：%s' % cycle)
    if carry:
        lines.append('- 流量结转：可结转至次月')
    lines.append('- 订购规则：%s' % _cell(cfg.get('order_rule')))
    lines.append('- 退订规则：%s' % _cell(cfg.get('cancel_rule')))
    ret: Output = {'config_summary': '\n'.join(lines)}
    return ret

